#!/usr/bin/env python3
from __future__ import annotations

import hashlib
import json
import re
from collections import Counter
from pathlib import Path

from build_dataset import contains_secret

ROOT = Path("/tmp/cnm-train31")
DATA = ROOT / "data"
STYLE_RE = {
    "conventional": re.compile(r"^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([^)]+\))?!?: .+"),
    "angular": re.compile(r"^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)\([^)]+\): [a-z\u4e00-\u9fff].+"),
}
DANGLING = {"a", "an", "and", "for", "from", "new", "of", "or", "the", "to", "unnecessary", "using", "via", "with"}


def load(name: str) -> list[dict]:
    return [json.loads(line) for line in (DATA / f"{name}.jsonl").read_text(encoding="utf-8").splitlines()]


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> int:
    splits = {name: load(name) for name in ("train", "valid", "test")}
    manifest = json.loads((DATA / "manifest.json").read_text(encoding="utf-8"))
    errors: list[str] = []
    family_sets: dict[str, set[str]] = {}
    repo_sets: dict[str, set[str]] = {}
    diff_sets: dict[str, set[str]] = {}
    for name, rows in splits.items():
        family_sets[name] = {row["meta"]["family"] for row in rows}
        repo_sets[name] = {row["meta"]["repo"] for row in rows}
        diff_sets[name] = set()
        for row in rows:
            diff = row["messages"][1]["content"].split("Git diff:\n", 1)[-1]
            diff_sets[name].add(hashlib.sha256(diff.encode()).hexdigest())
            if contains_secret(diff):
                errors.append(f"{row['meta']['id']}: secret scan")
        expected = manifest["splits"][name]
        if len(rows) != expected["records"]:
            errors.append(f"{name}: record count")
        if sha(DATA / f"{name}.jsonl") != expected["sha256"]:
            errors.append(f"{name}: sha256")
        for row in rows:
            target = row["messages"][-1]["content"].strip()
            subject = target.splitlines()[0] if target else ""
            style = row["meta"]["style"]
            guidance = row["meta"]["guidance"]
            if not target or len(subject) > 72 or "```" in target:
                errors.append(f"{row['meta']['id']}: target shape")
            if subject.endswith((":", ",", ";", "-")) or subject.lower().rsplit(" ", 1)[-1] in DANGLING:
                errors.append(f"{row['meta']['id']}: dangling subject")
            if style in STYLE_RE and not STYLE_RE[style].fullmatch(subject):
                errors.append(f"{row['meta']['id']}: {style} grammar")
            if "#123" in guidance and "#123" not in target:
                errors.append(f"{row['meta']['id']}: tracking guidance")
            if "SECURITY:" in guidance and not subject.startswith("SECURITY:"):
                errors.append(f"{row['meta']['id']}: security guidance")
            if "Simplified Chinese" in guidance and not re.search(r"[\u4e00-\u9fff]", target):
                errors.append(f"{row['meta']['id']}: Chinese guidance")
            if "exactly two" in guidance and sum(line.startswith("- ") for line in target.splitlines()) != 2:
                errors.append(f"{row['meta']['id']}: bullet guidance")
            if "paragraph beginning with `Why:`" in guidance and "\n\nWhy:" not in target:
                errors.append(f"{row['meta']['id']}: Why guidance")
    for a, b in (("train", "valid"), ("train", "test"), ("valid", "test")):
        for label, sets in (("family", family_sets), ("repo", repo_sets), ("diff", diff_sets)):
            if overlap := sets[a] & sets[b]:
                errors.append(f"{a}/{b}: {label} overlap {len(overlap)}")
    targets = [row["messages"][-1]["content"] for rows in splits.values() for row in rows]
    report = {
        "ok": not errors,
        "errors": errors[:100],
        "records": {name: len(rows) for name, rows in splits.items()},
        "families": {name: len(values) for name, values in family_sets.items()},
        "duplicate_target_groups": sum(count > 1 for count in Counter(targets).values()),
        "manifest_sha256": sha(DATA / "manifest.json"),
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0 if not errors else 1


if __name__ == "__main__":
    raise SystemExit(main())

